ROT = {
    'pt': ('SOBRE O PRATO', 'INGREDIENTES', 'PREPARO', 'MONTAGEM', 'DICA DO LIFE', ('porção', 'porções'), ':'),
    'en': ('ABOUT THE DISH', 'INGREDIENTS', 'PREPARATION', 'TO SERVE', "LIFE'S TIP", ('serving', 'servings'), ':'),
    'es': ('SOBRE EL PLATO', 'INGREDIENTES', 'PREPARACIÓN', 'MONTAJE', 'CONSEJO DE LIFE', ('porción', 'porciones'), ':'),
    'fr': ('À PROPOS DU PLAT', 'INGRÉDIENTS', 'PRÉPARATION', 'DRESSAGE', 'L’ASTUCE DE LIFE', ('portion', 'portions'), ' :'),
    'hi': ('इस डिश के बारे में', 'सामग्री', 'बनाने का तरीक़ा', 'परोसने का तरीक़ा', 'Life की टिप', ('सर्विंग', 'सर्विंग'), ':'),
}

def conteudo(lang, porcoes, t):
    sobre, ing, prep, mont, dica, (um, varios), dp = ROT[lang]
    unidade = um if porcoes == 1 else varios
    blocos = [
        f"{sobre}{dp} {t['sobre']}",
        f"{ing} ({porcoes} {unidade}){dp}\n" + '\n'.join(f'- {x}' for x in t['ing']),
        f"{prep}{dp}\n" + '\n'.join(f'{i}. {x}' for i, x in enumerate(t['prep'], 1)),
        f"{mont}{dp}\n" + '\n'.join(f'{i}. {x}' for i, x in enumerate(t['servir'], 1)),
        f"{dica}{dp} {t['dica']}",
    ]
    return '\n\n'.join(blocos)

